    c_star = sol_c0 + sol_c1 * T + sol_c2 * T * T
    sigma = c / c_star - 1.0

    # If already close to target temperature, slow down or stop
    if T <= T_target + 0.25:
        # Check if solution is equilibrated (sigma <= 0.02)
        if sigma <= 0.02:
            return 0.0  # Stop cooling

